292     <!-- Leaflet JS — ספריית המפה הראשית -->
293     <script src="https://unpkg.com/leaflet@1.9.4/dist/leaflet.js"></script>
294     <!-- Leaflet.heat — תוסף שכבת מפת חום חינמי -->
