297     <script>
298         // תיעוד שגיאות JS לא-תפוסות דרך שינוי document.title — מגיע ל-Python ב-_on_title_changed
299         // (הוסף כדי לאבחן שגיאת "Cannot read property 'getSize' of null" עם מיקום מדויק)
300         window.onerror = function(message, source, lineno, colno) {{
301             document.title = '__jserror__:' + message + ' @ ' + source + ':' + lineno + ':' + colno;
302             return false;
303         }};
304 
305         var map;                      // אובייקט המפה הראשי של Leaflet
306         var heatmap;                  // שכבת מפת החום (L.heatLayer)
307         var heatmapData = [];         // נתוני החום: מערך [[lat, lng, intensity], ...]
308         var allMarkers = [];          // מערך כל הסמנים — מאפשר ניקוי מרוכז מ-Python
309         var flightPolyline = null;    // קו מסלול הטיסה — null כשאין טיסה מוצגת
310         var flightMarker   = null;    // סמן מטוס במיקום הנוכחי
311         var _lastFlightRouteData = null;  // routeData המלא (כולל trail עם alt/spd/hd) של הטיסה האחרונה שנטענה — לשימוש בהערכת מסלול מול מכ"ם-דופלר
312         var _routeEvalLayers = [];    // קטעי הפוליליין הצבעוניים של הערכת המסלול האחרונה (לא flightPolyline הרגיל)
313         var _routeEvalRcsUsed = null; // ה-RCS שנגזר אוטומטית וששימש בהערכה האחרונה — מוצג ב-radarInfoEl בסיום, לשקיפות
314         var elevationLayer  = null;    // שכבת גבהים — null כשכבויה
315         var elevationActive = false;  // האם שכבת הגבהים פעילה
316         var elevationPoints = [];     // נקודות גובה {{lat, lng, elevation}} לפופאפ בלחיצה
317         var elevHandleState = {{ rect: null, handles: [] }};  // מלבן בחירה + 4 ידיות פינות אחרי טעינה
318         var tempHeatLayer   = null;   // שכבת מפת חום טמפרטורה — null כשכבויה
319         var tempSelectStart = null;   // נקודת תחילת בחירת אזור
320         var tempPreviewRect = null;   // מלבן preview בזמן גרירה
321         var tempSelecting   = false;  // האם המשתמש נמצא באמצע בחירת אזור
322         var _tempMDHandler  = null;   // פניה ל-mousedown handler לצורך ביטול
323         var tempHandleState = {{ rect: null, handles: [] }};  // מלבן בחירה + 4 ידיות פינות אחרי טעינה
324 
325         // ── מצב תצוגת שכבות ──
326         var elevDisplayMode = 'heat';  // 'heat' | 'grid' | 'dots'
327         var _elevRawData    = [];      // {{lat, lng, v}} ערך נורמלי 0-1
328         var elevGridLayer   = null;    // שכבת grid/dots לגבהים
329         var tempDisplayMode = 'heat';  // 'heat' | 'grid' | 'dots'
330         var _tempRawData    = [];      // {{lat, lng, v}} ערך נורמלי 0-1
331         var tempGridLayer   = null;    // שכבת grid/dots לטמפרטורה
332         var _elevGrad = [[0,[0,0,204]],[0.2,[0,170,255]],[0.4,[0,255,204]],[0.6,[170,255,0]],[0.8,[255,170,0]],[1,[204,0,0]]];
333         var _tempGrad = [[0,[0,0,204]],[0.25,[0,170,255]],[0.5,[0,255,204]],[0.75,[255,170,0]],[1,[204,0,0]]];
334 
335         var _mapReady = false;  // האם המפה סיימה להיטען — כפתורי LOS/רדיוס-ראייה מוצגים מיד אך מנוטרלים עד אז (map.whenReady, בהמשך)
336 
337         // ── Undo/Redo גנרי — מחסנית פעולות משותפת לכל הכלים, לא ספציפית לכלי אחד ──
338         // כל "פעולה" (עריכת שדה, מיקום משקיף, הרצת חישוב, הצבת/איפוס שכבה) נרשמת כזוג
339         // get/set + הערך הקודם. undo/redo זהים למעשה — כל אחד רק מחליף כיוון על אותה מחסנית.
340         var _undoStack = [];  // [{{label, restore}}, ...] — restore() משחזר אחורה ומחזיר בתמורה פונקציית הפוך ל-redo
341         var _redoStack = [];
342         var _UNDO_MAX = 50;  // תקרה סבירה — מונע צריכת זיכרון בלתי מוגבלת בסשן ארוך
343         var _undoBtnEl = null, _redoBtnEl = null;  // הפניות לכפתורי הסרגל, לעדכון enabled/disabled
344         var _isRestoringUndo = false;  // true תוך כדי ביצוע undo/redo עצמו — מונע ממאזיני 'change'/'blur'
345         // (שמותקנים כדי *לרשום* פעולות חדשות) לתפוס את השינוי התכנותי-שלנו-עצמנו כפעולה חדשה,
346         // מה שהיה יוצר לולאה/מציף את המחסניות בכל undo יחיד
347 
348         function _pushUndo(label, restoreFn) {{
349             if (_isRestoringUndo) return;  // הגנה נוספת — לא אמור לקרות, אבל עדיף לא לרשום undo בתוך undo
350             _undoStack.push({{label: label, restore: restoreFn}});
351             if (_undoStack.length > _UNDO_MAX) _undoStack.shift();  // מוחק את הישן ביותר אם עברנו את התקרה
352             _redoStack = [];  // כל פעולה חדשה מבטלת redo קודם — התנהגות סטנדרטית בכל תוכנה
353             _updateUndoRedoButtons();
354         }}
355 
356         // הליבה הגנרית: setFn/getFn מתארים "איך לקרוא/לכתוב" את הערך (שדה DOM, מיקום משקיף,
357         // דגל שכבה וכו') — לא תלוי בסוג הפעולה. מחזיר פונקציה שכשנקראת: קוראת את הערך הנוכחי
358         // (לפני שהיא דורסת אותו — זה מה ש-redo/undo הבא יצטרך), כותבת את targetValue, ומחזירה
359         // עצמה-מחדש (closure רקורסיבי) עבור הכיוון ההפוך — כך undo ו-redo משתמשים באותה פונקציה.
360         function _makeValueRestore(setFn, getFn, targetValue, onApply) {{
361             return function() {{
362                 var current = getFn();
363                 setFn(targetValue);
364                 if (onApply) onApply();
365                 return _makeValueRestore(setFn, getFn, current, onApply);
366             }};
367         }}
368 
369         // גרסה גנרית ל"הזזת" סמן קיים (למשל גרירת משקיף/יעד) — לא יוצרת/מוחקת דבר, רק מזיזה חזרה
370         function _makeMarkerMoveRestore(setPosFn, getPosFn, updateFn, targetLatLng) {{
371             return function() {{
372                 var current = getPosFn();
373                 setPosFn(targetLatLng);
374                 if (updateFn) updateFn();
375                 return _makeMarkerMoveRestore(setPosFn, getPosFn, updateFn, current);
376             }};
377         }}
378 
379         // גרסה גנרית ל"הצבה" מלאה (למשל לחיצה על המפה שממקמת/מחליפה משקיף) —
380         // אם אין ערך קודם (null) קוראת ל-clearFn (מחזירה למצב "אין עדיין הצבה")
381         function _makePlacementRestore(placeFn, clearFn, getPosFn, targetLatLngOrNull) {{
382             return function() {{
383                 var current = getPosFn();
384                 if (targetLatLngOrNull) {{ placeFn(targetLatLngOrNull); }} else {{ clearFn(); }}
385                 return _makePlacementRestore(placeFn, clearFn, getPosFn, current);
386             }};
387         }}
388 
389         // ── עזרי Undo ייעודיים לכלי קו-הראייה (LOS) — מבנה שונה משאר הכלים: כל צמד לחיצות יוצר
390         // סשן חדש במערך losSessions (לא מצב יחיד שמוחלף), ולכן דרוש היפוך "קיים/לא-קיים" ולא "ערך קודם"
391         function _addLosSessionToMap(session) {{
392             if (losSessions.indexOf(session) === -1) losSessions.push(session);
393             if (session.obsMk) session.obsMk.addTo(map);
394             if (session.tgtMk) session.tgtMk.addTo(map);
395             session.lineLayers.forEach(function(l) {{ l.addTo(map); }});
396         }}
397 
398         function _removeLosSessionFromMap(session) {{
399             var idx = losSessions.indexOf(session);
400             if (idx !== -1) losSessions.splice(idx, 1);
401             if (session.obsMk) map.removeLayer(session.obsMk);
402             if (session.tgtMk) map.removeLayer(session.tgtMk);
403             session.lineLayers.forEach(function(l) {{ map.removeLayer(l); }});
404         }}
405 
406         function _makeLosSessionRestore(session, isPresent) {{
407             return function() {{
408                 if (isPresent) {{ _removeLosSessionFromMap(session); }} else {{ _addLosSessionToMap(session); }}
409                 return _makeLosSessionRestore(session, !isPresent);
410             }};
411         }}
412 
413         // "הצבעה" זמנית — נקודת התצפית שנקבעה בלחיצה הראשונה, לפני שנבחר יעד (עדיין אין סשן)
414         function _makeLosPendingObsRestore(mk, latlng, isPresent) {{
415             return function() {{
416                 if (isPresent) {{
417                     map.removeLayer(mk); losCurObs = null; losCurObsMk = null;
418                 }} else {{
419                     losCurObs = latlng; losCurObsMk = mk; mk.addTo(map);
420                 }}
421                 return _makeLosPendingObsRestore(mk, latlng, !isPresent);
422             }};
423         }}
424 
425         // גרסה גנרית ל"תיבת-סימון לוגית" (בוליאני שנקבע ע"י פונקציית toggle קיימת, לא ע"י setter ישיר) —
426         // בשימוש עבור שכבות NOTAM/אזורי-תיאום/CTR, שתיבות הסימון שלהן הן ווידג'טים של Qt (לא DOM),
427         // ולכן לא ניתן לחווט אותן ישירות עם _attachCheckboxUndo הרגיל — ה-toggle עצמו נקרא במקום.
428         function _makeSimpleToggleRestore(toggleFn, getFn, targetBool) {{
429             return function() {{
430                 var current = getFn();
431                 if (current !== targetBool) toggleFn();  // קורא ל-toggle המקורי רק אם המצב בפועל אכן שונה מהיעד
432                 return _makeSimpleToggleRestore(toggleFn, getFn, current);
433             }};
434         }}
435 
436         function _performUndo() {{
437             if (!_undoStack.length || _isRestoringUndo) return;
438             var entry = _undoStack.pop();
439             _isRestoringUndo = true;
440             var forward;
441             try {{ forward = entry.restore(); }} finally {{ _isRestoringUndo = false; }}  // מבצע את השחזור בפועל, מקבל בתמורה פונקציית הפוך
442             _redoStack.push({{label: entry.label, restore: forward}});
443             _updateUndoRedoButtons();
444             // מאותת ל-Python (main.py, ר' _on_title_changed) ליישר תיבות/כפתורי שכבות NOTAM/תיאום/CTR —
445             // אלה ווידג'טים של Qt מחוץ לדף, ולכן לא מתעדכנים אוטומטית כשה-JS משנה מצב ישירות (בלי לחיצה על הכפתור עצמו)
446             document.title = '__sync_layer_checkboxes__';
447         }}
448 
449         function _performRedo() {{
450             if (!_redoStack.length || _isRestoringUndo) return;
451             var entry = _redoStack.pop();
452             _isRestoringUndo = true;
453             var backward;
454             try {{ backward = entry.restore(); }} finally {{ _isRestoringUndo = false; }}
455             _undoStack.push({{label: entry.label, restore: backward}});
456             _updateUndoRedoButtons();
457             document.title = '__sync_layer_checkboxes__';  // ר' הערה מקבילה ב-_performUndo
458         }}
459 
460         function _updateUndoRedoButtons() {{
461             if (_undoBtnEl) _undoBtnEl.style.opacity = _undoStack.length ? '1' : '0.35';
462             if (_redoBtnEl) _redoBtnEl.style.opacity = _redoStack.length ? '1' : '0.35';
463         }}
464 
465         // עוזר נפוץ: רושם undo לשינוי ערך שדה DOM בודד (input/select) — el.value לפני/אחרי.
466         // לא רושם אם הערך בפועל לא השתנה (מונע פקודות undo מיותרות, למשל focus+blur בלי עריכה).
467         function _recordFieldUndo(el, beforeValue, label, onApply) {{
468             if (_isRestoringUndo || el.value === beforeValue) return;
469             _pushUndo(label, _makeValueRestore(
470                 function(v) {{ el.value = v; }},
471                 function() {{ return el.value; }},
472                 beforeValue, onApply
473             ));
474         }}
475 
476         // מצרף לשדה DOM מעקב focus→blur לרישום undo אוטומטי — נקרא פעם אחת לכל שדה בזמן בנייתו
477         // (מתוך _mkField של כל כלי), כדי לא לשכפל את לוגיקת ה-focus/blur הזו בכל כלי בנפרד.
478         function _attachFieldUndo(el, label, onApply) {{
479             var focusValue = null;
480             L.DomEvent.on(el, 'focus', function() {{ focusValue = el.value; }});
481             L.DomEvent.on(el, 'blur', function() {{
482                 if (focusValue !== null) _recordFieldUndo(el, focusValue, label, onApply);
483                 focusValue = null;
484             }});
485         }}
486 
487         // מקביל ל-_attachFieldUndo, אבל ל-<select> (משתנה אטומית ב-'change', אין focus/blur
488         // הדרגתי כמו בטקסט) — בשחזור גם משגר אירוע 'change' אמיתי, כדי שכל מאזין חיצוני
489         // שתלוי בבחירה הזו (למשל חשיפת שדות מערך-מופעים) יתעדכן ממילא, בלי שנצטרך להכיר אותו.
490         function _attachSelectUndo(sel, label) {{
491             var prevValue = sel.value;
492             L.DomEvent.on(sel, 'change', function() {{
493                 if (_isRestoringUndo) {{ prevValue = sel.value; return; }}
494                 var before = prevValue;
495                 if (sel.value !== before) {{
496                     _pushUndo(label, _makeValueRestore(
497                         function(v) {{ sel.value = v; sel.dispatchEvent(new Event('change')); }},
498                         function() {{ return sel.value; }},
499                         before, null
500                     ));
501                 }}
502                 prevValue = sel.value;
503             }});
504         }}
505 
506         // מקביל ל-_attachSelectUndo, אבל ל-checkbox (.checked בוליאני, לא .value מחרוזת)
507         function _attachCheckboxUndo(chk, label) {{
508             var prevChecked = chk.checked;
509             L.DomEvent.on(chk, 'change', function() {{
510                 if (_isRestoringUndo) {{ prevChecked = chk.checked; return; }}
511                 var before = prevChecked;
512                 if (chk.checked !== before) {{
513                     _pushUndo(label, _makeValueRestore(
514                         function(v) {{ chk.checked = v; chk.dispatchEvent(new Event('change')); }},
515                         function() {{ return chk.checked; }},
516                         before, null
517                     ));
518                 }}
519                 prevChecked = chk.checked;
520             }});
521         }}
522 
523         // קיצורי מקלדת גלובליים — Ctrl+Z (undo), Ctrl+Y או Ctrl+Shift+Z (redo, שני המוסכמות
524         // הנפוצות). מוגדר ברמת document כדי לעבוד מכל מקום בעמוד, גם כששדה קלט ממוקד.
525         document.addEventListener('keydown', function(e) {{
526             if (!(e.ctrlKey || e.metaKey)) return;
