663         function _normToColor(n, grad) {{
664             for (var i = 1; i < grad.length; i++) {{
665                 if (n <= grad[i][0]) {{
666                     var t = (n - grad[i-1][0]) / (grad[i][0] - grad[i-1][0]);
667                     var a = grad[i-1][1], b = grad[i][1];
668                     return 'rgb(' + Math.round(a[0]+t*(b[0]-a[0])) + ',' + Math.round(a[1]+t*(b[1]-a[1])) + ',' + Math.round(a[2]+t*(b[2]-a[2])) + ')';
669                 }}
670             }}
671             var last = grad[grad.length-1][1];
672             return 'rgb(' + last[0] + ',' + last[1] + ',' + last[2] + ')';
673         }}
674 
675         function _normToColorArr(n, grad) {{
676             for (var i = 1; i < grad.length; i++) {{
677                 if (n <= grad[i][0]) {{
678                     var t = (n - grad[i-1][0]) / (grad[i][0] - grad[i-1][0]);
679                     var a = grad[i-1][1], b = grad[i][1];
680                     return [Math.round(a[0]+t*(b[0]-a[0])), Math.round(a[1]+t*(b[1]-a[1])), Math.round(a[2]+t*(b[2]-a[2]))];
681                 }}
682             }}
683             return grad[grad.length-1][1].slice();
684         }}
