688         // בונה קנבס-תמונה מרשת נקודות ערך (גבהים/טמפרטורה) — משותף לשתי השכבות,
689         // rawData/grad/opacity מגיעים כפרמטרים כדי לשמר בדיוק את אותה התנהגות לכל שכבה.
690         function _buildValueCanvas(rawData, grad, opacity) {{
691             if (rawData.length < 4) return null;
692             var latSet = {{}}, lngSet = {{}};
693             rawData.forEach(function(p) {{ latSet[p.lat.toFixed(6)] = 1; lngSet[p.lng.toFixed(6)] = 1; }});
694             var lats = Object.keys(latSet).map(Number).sort(function(a,b){{return a-b;}});
695             var lngs = Object.keys(lngSet).map(Number).sort(function(a,b){{return a-b;}});
696             var nLat = lats.length, nLng = lngs.length;
697             if (nLat < 2 || nLng < 2) return null;
698             var dlat = (lats[nLat-1] - lats[0]) / (nLat - 1);
699             var dlng = (lngs[nLng-1] - lngs[0]) / (nLng - 1);
700             var vals = [];
701             for (var i = 0; i < nLat; i++) {{ vals[i] = []; for (var j = 0; j < nLng; j++) vals[i][j] = 0.5; }}
702             rawData.forEach(function(p) {{
703                 var li = Math.round((p.lat - lats[0]) / dlat);
704                 var lj = Math.round((p.lng - lngs[0]) / dlng);
705                 if (li >= 0 && li < nLat && lj >= 0 && lj < nLng) vals[li][lj] = p.v;
706             }});
707             var pxPerCell = 12;
708             var W = Math.max(60, nLng * pxPerCell), H = Math.max(60, nLat * pxPerCell);
709             var canvas = document.createElement('canvas');
710             canvas.width = W; canvas.height = H;
711             var ctx = canvas.getContext('2d');
712             var imgData = ctx.createImageData(W, H);
713             var alpha = Math.round(opacity * 255);
714             var minLat = lats[0], maxLat = lats[nLat-1];
715             var minLng = lngs[0], maxLng = lngs[nLng-1];
716             for (var py = 0; py < H; py++) {{
717                 var lat = maxLat - (py / (H - 1)) * (maxLat - minLat);
718                 var fi = Math.max(0, Math.min(nLat - 1.0001, (lat - minLat) / dlat));
719                 var i0 = Math.floor(fi), i1 = i0 + 1 < nLat ? i0 + 1 : i0;
720                 var ti = fi - i0;
721                 for (var px = 0; px < W; px++) {{
722                     var lng = minLng + (px / (W - 1)) * (maxLng - minLng);
723                     var fj = Math.max(0, Math.min(nLng - 1.0001, (lng - minLng) / dlng));
724                     var j0 = Math.floor(fj), j1 = j0 + 1 < nLng ? j0 + 1 : j0;
725                     var tj = fj - j0;
726                     var v = vals[i0][j0]*(1-ti)*(1-tj) + vals[i0][j1]*(1-ti)*tj +
727                              vals[i1][j0]*ti*(1-tj)     + vals[i1][j1]*ti*tj;
728                     var c = _normToColorArr(v, grad);
729                     var idx = (py * W + px) * 4;
730                     imgData.data[idx]=c[0]; imgData.data[idx+1]=c[1]; imgData.data[idx+2]=c[2]; imgData.data[idx+3]=alpha;
731                 }}
732             }}
733             ctx.putImageData(imgData, 0, 0);
734             return {{ canvas: canvas, bounds: [[minLat - dlat/2, minLng - dlng/2], [maxLat + dlat/2, maxLng + dlng/2]] }};
735         }}
