982         function _haversineM(p1, p2) {{
983             var R = 6371000, r = Math.PI/180;
984             var f1=p1.lat*r, f2=p2.lat*r, df=(p2.lat-p1.lat)*r, dl=(p2.lng-p1.lng)*r;
985             var a = Math.sin(df/2)*Math.sin(df/2)+Math.cos(f1)*Math.cos(f2)*Math.sin(dl/2)*Math.sin(dl/2);
986             return R * 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1-a));
987         }}
988 
989         function _bearingDeg(p1, p2) {{
990             // אזימוט התחלתי (0=צפון, בכיוון השעון) מ-p1 אל p2 — נוסחת "initial bearing" סטנדרטית.
991             // משמש לחישוב הזווית בזמן גרירת ידית רדיוס-הראייה הרדיאלי — חישוב JS מקומי, לא קורא לשרת.
992             var r = Math.PI/180;
993             var f1=p1.lat*r, f2=p2.lat*r, dl=(p2.lng-p1.lng)*r;
994             var y = Math.sin(dl) * Math.cos(f2);
995             var x = Math.cos(f1)*Math.sin(f2) - Math.sin(f1)*Math.cos(f2)*Math.cos(dl);
996             var brng = Math.atan2(y, x) / r;
997             return (brng + 360) % 360;  // נרמול ל-[0,360)
998         }}
999 
1000         function _destPointJs(origin, bearingDeg, distanceM) {{
1001             // גרסת JS של _destination_point הפייתוני (weather_server.py) — נקודת יעד ממקור+אזימוט+מרחק,
1002             // קירוב כדורי. משמש לצייר את קווי התצוגה המקדימה של רדיוס-הראייה הרדיאלי בלי לקרוא לשרת.
1003             if (distanceM <= 0) return L.latLng(origin.lat, origin.lng);
1004             var r = Math.PI/180, R = 6371000;
1005             var phi1 = origin.lat*r, lam1 = origin.lng*r, theta = bearingDeg*r, delta = distanceM/R;
1006             var phi2 = Math.asin(Math.sin(phi1)*Math.cos(delta) + Math.cos(phi1)*Math.sin(delta)*Math.cos(theta));
1007             var lam2 = lam1 + Math.atan2(
1008                 Math.sin(theta)*Math.sin(delta)*Math.cos(phi1),
1009                 Math.cos(delta) - Math.sin(phi1)*Math.sin(phi2)
1010             );
1011             return L.latLng(phi2/r, ((lam2/r + 540) % 360) - 180);  // נרמול קו האורך ל-[-180,180]
1012         }}
