1689         // state = {{rect, handles}} נפרד לכל שכבה (elevHandleState/tempHandleState), כדי לשמר
1690         // ציור/מצב עצמאיים; color/eps/onFinish הם הפרמטרים שבאמת שונים בין שתי השכבות.
1691         function _clearRegionHandles(state) {{
