1697         function _drawRegionHandles(state, color, bounds, eps, onFinish) {{
1698             _clearRegionHandles(state);
1699             state.rect = L.rectangle(bounds, {{
1700                 color: color, weight: 1.5, dashArray: '5,4', fillOpacity: 0, interactive: false
1701             }}).addTo(map);
1702             var sw = bounds.getSouthWest(), ne = bounds.getNorthEast();
1703             var corners = [sw, L.latLng(sw.lat, ne.lng), ne, L.latLng(ne.lat, sw.lng)];
1704             var handleHtml = '<div style="width:12px;height:12px;background:' + color + ';border:2px solid #fff;'
1705                            + 'border-radius:3px;cursor:move;box-shadow:0 1px 3px rgba(0,0,0,.4);"></div>';
1706             var handleIcon = L.divIcon({{ html: handleHtml, className: '', iconSize: [12,12], iconAnchor: [6,6] }});
1707             corners.forEach(function(corner, i) {{
1708                 var h = L.marker(corner, {{ icon: handleIcon, draggable: true, zIndexOffset: 900 }}).addTo(map);
1709                 h.on('drag', function(ev) {{
1710                     var p = ev.target.getLatLng();
1711                     var cur = state.rect.getBounds();
1712                     var s=cur.getSouth(), n=cur.getNorth(), w=cur.getWest(), e=cur.getEast();
1713                     if (i===0){{s=p.lat;w=p.lng;}} else if (i===1){{s=p.lat;e=p.lng;}}
1714                     else if (i===2){{n=p.lat;e=p.lng;}} else {{n=p.lat;w=p.lng;}}
1715                     var nb = L.latLngBounds([[s,w],[n,e]]);
1716                     state.rect.setBounds(nb);
1717                     var nsw=nb.getSouthWest(), nne=nb.getNorthEast();
1718                     var nc=[nsw,L.latLng(nsw.lat,nne.lng),nne,L.latLng(nne.lat,nsw.lng)];
1719                     state.handles.forEach(function(hh,j){{ if(j!==i) hh.setLatLng(nc[j]); }});
1720                 }});
1721                 h.on('dragend', function() {{
1722                     var nb = state.rect.getBounds();
1723                     var sw2=nb.getSouthWest(), ne2=nb.getNorthEast();
1724                     if (Math.abs(ne2.lat-sw2.lat)<eps || Math.abs(ne2.lng-sw2.lng)<eps) return;
1725                     onFinish(nb);
1726                 }});
1727                 state.handles.push(h);
1728             }});
1729         }}
