1780         function _loadElevationForBounds(bounds) {{
1781             var sw    = bounds.getSouthWest();  // פינה דרום-מערבית של האזור שנבחר
1782             var ne    = bounds.getNorthEast();  // פינה צפון-מזרחית של האזור שנבחר
1783             document.title = '__elev_computing__';
1784             var steps = 9;                      // רשת 10×10 = 100 נקודות — מגבלת Open-Meteo לבקשה אחת
1785             var locations = [];                 // מערך הנקודות שייבנה ויישלח לשרת
1786 
1787             // בניית רשת אחידה של נקודות על פני האזור שנבחר בלבד
1788             for (var i = 0; i <= steps; i++) {{
1789                 for (var j = 0; j <= steps; j++) {{
1790                     locations.push({{
1791                         latitude:  sw.lat + (ne.lat - sw.lat) * i / steps,  // קו רוחב: מדרום לצפון
1792                         longitude: sw.lng + (ne.lng - sw.lng) * j / steps   // קו אורך: ממערב למזרח
1793                     }});
1794                 }}
1795             }}
1796 
1797             // שליחת בקשה לשרת המקומי שמעביר ל-Open-Meteo
1798             fetch('http://localhost:5002/elevation', {{
1799                 method:  'POST',                                    // POST — הנקודות בגוף הבקשה
1800                 headers: {{'Content-Type': 'application/json'}},    // הצהרת סוג תוכן
1801                 body:    JSON.stringify({{locations: locations}})    // המרת הנקודות ל-JSON
1802             }})
1803             .then(function(r) {{
1804                 if (r.status === 429) return r.json().then(function(d) {{ throw new Error('מכסת API יומית נוצלה — נסה שוב מחר. ' + (d.reason || '')); }});
1805                 if (!r.ok) throw new Error('שגיאת שרת: ' + r.status);  // בדיקת קוד התגובה
1806                 return r.json();                                          // פירוק ה-JSON
1807             }})
1808             .then(function(data) {{
1809                 var results = data.results || [];                           // רשימת הנקודות עם גבהים
1810                 if (!results.length) throw new Error('אין נתוני גובה');   // בדיקת תוכן
1811 
1812                 // שמירת נקודות הגובה לפופאפ בלחיצה
1813                 elevationPoints = results.map(function(p) {{
1814                     return {{ lat: p.latitude, lng: p.longitude, elevation: p.elevation }};
1815                 }});
1816 
1817                 // נרמול הגבהים לטווח 0–1 ושמירה לשינוי מצב תצוגה
1818                 var elevations = results.map(function(p) {{ return p.elevation; }});
1819                 var minE  = Math.min.apply(null, elevations);
1820                 var maxE  = Math.max.apply(null, elevations);
1821                 var range = maxE - minE || 1;
1822                 _elevRawData = results.map(function(p) {{
1823                     return {{ lat: p.latitude, lng: p.longitude, v: (p.elevation - minE) / range, raw: p.elevation }};
1824                 }});
1825 
1826                 _rebuildElevLayer();
1827                 document.title = '__elev_loaded__';
1828             }})
1829             .catch(function(err) {{
1830                 console.error('שגיאת שכבת גבהים:', err);
1831                 elevationActive = false;
1832                 document.title = '__elev_error__';
1833             }});
1834         }}
