1975         function _calcTempRadius() {{
1976             var zoom     = map.getZoom();
1977             var pixPerKm = 256 * Math.pow(2, zoom) / 360 / 111 * Math.cos(31.5 * Math.PI / 180);
1978             return Math.max(10, Math.round(5 * pixPerKm * 0.65));
1979         }}
