1985         function _calcTempMax() {{
1986             var zoom     = map.getZoom();
1987             var pixPerKm = 256 * Math.pow(2, zoom) / 360 / 111 * Math.cos(31.5 * Math.PI / 180);
1988             var gridPx   = 5 * pixPerKm;
1989             var r        = _calcTempRadius();
1990             return Math.max(1, Math.PI * r * r / (gridPx * gridPx));
1991         }}
