2151         function fetchWeather(lat, lon) {{
2152             // שליפת מזג אוויר וגובה במקביל — Promise.all מבטיח תצוגה אחת לאחר שתי התשובות
2153             var weatherPromise = fetch(`http://localhost:5002/weather?lat=${{lat}}&lon=${{lon}}`)
2154                 .then(function(r) {{
2155                     if (!r.ok) throw new Error('HTTP ' + r.status);
2156                     return r.json();
2157                 }});
2158 
2159             var elevationPromise = fetch('http://localhost:5002/elevation', {{
2160                 method:  'POST',
2161                 headers: {{'Content-Type': 'application/json'}},
2162                 body:    JSON.stringify({{locations: [{{latitude: parseFloat(lat), longitude: parseFloat(lon)}}]}})
2163             }})
2164             .then(function(r) {{ return r.ok ? r.json() : null; }})
2165             .catch(function() {{ return null; }});  // כשל בגובה לא מונע הצגת מזג אוויר
2166 
2167             Promise.all([weatherPromise, elevationPromise])
2168                 .then(function(results) {{
2169                     var data    = results[0];
2170                     var elevRes = results[1];
2171                     if (!data.weather || !data.temperature) {{
2172                         throw new Error("הנתונים שהתקבלו אינם כוללים מזג אוויר או טמפרטורה");
2173                     }}
2174                     var elevation = null;
2175                     if (elevRes && elevRes.results && elevRes.results.length > 0) {{
2176                         elevation = elevRes.results[0].elevation;
2177                     }}
2178                     displayWeatherOnMap(lat, lon, data, elevation);
2179                 }})
2180                 .catch(function(error) {{
2181                     console.error("Error fetching weather data:", error.message);
2182                     alert("לא ניתן להחזיר נתוני מזג האוויר: " + error.message);
2183                 }});
2184         }}
