2272         // פונקציה: שליחת בקשת LOS לשרת ועדכון הסשן הספציפי בתשובה
2273         // obs = LatLng תצפית, tgt = LatLng יעד, session = אובייקט הסשן לעדכון
2274         function _runLos(obs, tgt, session) {{
2275             document.title = '__los_loading__';  // איתות ל-Python: חישוב החל
2276             // בניית URL עם קואורדינטות שתי הנקודות וגבהי הצופה/היעד שנשמרו על הסשן ביצירתו
2277             var url = 'http://localhost:5002/los?lat1=' + obs.lat + '&lon1=' + obs.lng +
2278                       '&lat2=' + tgt.lat + '&lon2=' + tgt.lng +
2279                       '&obs_h=' + (session.obsH != null ? session.obsH : 11) +
2280                       '&tgt_h=' + (session.tgtH != null ? session.tgtH : 0);
2281             fetch(url)
2282             .then(function(r) {{
2283                 if (!r.ok) throw new Error('HTTP ' + r.status);  // שגיאת HTTP
2284                 return r.json();                                   // פענוח JSON
2285             }}).then(function(data) {{
2286                 if (data.error) throw new Error(data.error);       // שגיאה מהשרת
2287                 session.data = data;               // שמירת נתוני התשובה באובייקט הסשן
2288                 document.title = '__los_loaded__'; // איתות ל-Python: חישוב הצליח
2289                 _drawLosOnMap(session);            // ציור קווים על המפה עבור הסשן הזה
2290                 _redrawPanel();                    // בניית מחדש של הפאנל עם כל הסשנים
2291             }}).catch(function(err) {{
2292                 // כישלון בחישוב ראשוני (לסשן שעדיין אין לו נתונים) — הסרת הסשן כי אין לו מה להציג
2293                 // כישלון בחישוב מחדש אחרי גרירה (יש כבר data קודם) — משאירים את הסשן והקווים הישנים במקום
2294                 if (!session.data) {{
2295                     var sIdx = losSessions.indexOf(session);
2296                     if (sIdx !== -1) {{
2297                         if (session.obsMk) map.removeLayer(session.obsMk);  // ניקוי סמן תצפית
2298                         if (session.tgtMk) map.removeLayer(session.tgtMk);  // ניקוי סמן יעד
2299                         losSessions.splice(sIdx, 1);  // הסרה מהמערך
2300                     }}
2301                 }}
2302                 document.title = '__los_error__';  // איתות ל-Python: שגיאה
2303                 console.error('LOS error:', err);
2304                 alert('שגיאה בחישוב קו ראייה ' + session.idx + ': ' + err.message);
2305             }});
