2308         // פונקציה: ציור קווי LOS של סשן אחד על המפה (ירוק=גלוי, אדום=חסום)
2309         // האלגוריתם: איחוד נקודות עוקבות עם אותו סטטוס לקטע בצבע אחיד
2310         function _drawLosOnMap(session) {{
2311             session.lineLayers.forEach(function(l) {{ map.removeLayer(l); }});  // ניקוי קווים ישנים של הסשן
2312             session.lineLayers = [];  // איפוס
2313             var pts = session.data.points;       // נקודות המסלול מהשרת
2314             if (!pts || pts.length < 2) return;  // מינימום 2 נקודות
2315             var seg    = [];
2316             var curVis = pts[0].visible;  // סטטוס ראייה של הנקודה הראשונה
2317             for (var i = 0; i < pts.length; i++) {{
2318                 var p  = pts[i];
2319                 var ll = [p.lat, p.lon];  // פורמט [lat, lon] לאובייקטי Leaflet
2320                 if (i === 0) {{ seg.push(ll); continue; }}  // נקודה ראשונה — מתחילים קטע, אין קו עדיין
2321                 if (p.visible === curVis) {{
2322                     seg.push(ll);  // אותו סטטוס — ממשיכים לאסוף לקטע הנוכחי
2323                 }} else {{
2324                     // שינוי ראות — ציור הקטע שנאסף ופתיחת קטע חדש
2325                     var color = curVis ? '#00cc44' : '#ff3300';  // ירוק/אדום
2326                     session.lineLayers.push(L.polyline(seg, {{color:color, weight:4, opacity:0.85}}).addTo(map));
2327                     seg    = [seg[seg.length - 1], ll];  // הקטע החדש מתחיל מנקודת הגבול (חיבור חלק)
2328                     curVis = p.visible;                   // עדכון סטטוס הקטע הנוכחי
2329                 }}
2330             }}
2331             if (seg.length >= 2) {{
2332                 // ציור הקטע האחרון שנשאר לאחר סיום הלולאה
2333                 var color = curVis ? '#00cc44' : '#ff3300';
2334                 session.lineLayers.push(L.polyline(seg, {{color:color, weight:4, opacity:0.85}}).addTo(map));
2335             }}
