2402         // פונקציה: ציור פרופיל שטח + קו ראייה עבור סשן בודד על canvas נתון
2403         // canvas = אלמנט canvas, session = אובייקט הסשן (עם session.data מהשרת)
2404         function _drawProfileSingle(canvas, session) {{
2405             var data = session.data;
2406             if (!data || !data.points || data.points.length < 2) return;  // בטיחות
2407             // קביעת גודל ה-canvas לגודל ה-DOM בפועל — נחוץ כי CSS לבדו לא מגדיר pixel size
2408             canvas.width  = canvas.offsetWidth  || 200;
2409             canvas.height = canvas.offsetHeight || 180;
2410             var ctx = canvas.getContext('2d');  // הקשר ציור דו-ממדי
2411             var pts = data.points;
2412             var W = canvas.width, H = canvas.height;
2413             // שוליים: l לציר Y, r ימין, t עליון (לכותרת), b תחתון (לציר X)
2414             var PAD = {{l:44, r:6, t:18, b:24}};
2415             var cW = W - PAD.l - PAD.r;  // רוחב אזור הגרף
2416             var cH = H - PAD.t - PAD.b;  // גובה אזור הגרף
2417 
2418             // חישוב טווח גבהים — כולל גם גובה השטח וגם גובה קו הראייה
2419             var minE = Infinity, maxE = -Infinity;
2420             pts.forEach(function(p) {{
2421                 if (p.elevation < minE) minE = p.elevation;
2422                 if (p.elevation > maxE) maxE = p.elevation;
2423                 if (p.los_h     < minE) minE = p.los_h;
2424                 if (p.los_h     > maxE) maxE = p.los_h;
2425             }});
2426             var eRange = maxE - minE || 1;  // || 1 מונע חלוקה באפס
2427 
2428             // המרת אינדקס נקודה → X בפיקסלים
2429             function xOf(i)   {{ return PAD.l + (i / (pts.length - 1)) * cW; }}
2430             // המרת גובה → Y בפיקסלים (הפוכה: גבוה=Y קטן כי canvas מניה מלמעלה)
2431             function yOf(val) {{ return PAD.t + cH - (val - minE) / eRange * cH; }}
2432 
2433             // רקע כהה
2434             ctx.fillStyle = '#1e1e2e'; ctx.fillRect(0, 0, W, H);
2435 
2436             // ציר Y — 4 חלוקות עם קווי רשת ותוויות גובה
2437             ctx.fillStyle = '#666'; ctx.font = '9px Arial'; ctx.textAlign = 'right';
2438             for (var s = 0; s <= 3; s++) {{
2439                 var val = minE + (eRange * s / 3);  // ערך גובה לכל חלוקה
2440                 var y   = yOf(val);
2441                 ctx.fillText(Math.round(val) + 'מ', PAD.l - 3, y + 3);  // תווית ציר Y
2442                 ctx.strokeStyle = '#2a2a3e'; ctx.lineWidth = 0.5;         // קו רשת
2443                 ctx.beginPath(); ctx.moveTo(PAD.l, y); ctx.lineTo(PAD.l + cW, y); ctx.stroke();
2444             }}
2445 
2446             // ציר X — עד 6 תוויות מרחק בק"מ
2447             ctx.fillStyle = '#666'; ctx.textAlign = 'center'; ctx.font = '9px Arial';
2448             var xSteps = Math.min(6, pts.length - 1);  // לא יותר נקודות ממה שיש
2449             for (var xi = 0; xi <= xSteps; xi++) {{
2450                 var idx = Math.round(xi / xSteps * (pts.length - 1));
2451                 ctx.fillText(pts[idx].dist_km + '', xOf(idx), PAD.t + cH + 14);  // מרחק בק"מ
2452             }}
2453 
2454             // שטח טופוגרפיה — מצולע סגור מלא בירוק-זית שקוף
2455             ctx.beginPath();
2456             ctx.moveTo(xOf(0), yOf(pts[0].elevation));
2457             for (var i = 1; i < pts.length; i++) {{
2458                 ctx.lineTo(xOf(i), yOf(pts[i].elevation));  // קו לכל נקודת שטח
2459             }}
2460             ctx.lineTo(xOf(pts.length - 1), PAD.t + cH);  // ירידה לבסיס (ציר X)
2461             ctx.lineTo(xOf(0), PAD.t + cH);                // חזרה לנקודת ההתחלה
2462             ctx.closePath();
2463             ctx.fillStyle   = 'rgba(101,163,13,0.45)'; ctx.fill();
2464             ctx.strokeStyle = '#65a30d'; ctx.lineWidth = 1; ctx.stroke();
2465 
2466             // קו הראייה — קטע לכל זוג נקודות עוקבות, ירוק=גלוי / אדום=חסום
2467             // los_h = הגובה המינימלי שמאפשר ראייה לנקודה זו מנקודת התצפית
2468             for (var i = 1; i < pts.length; i++) {{
2469                 ctx.beginPath();
2470                 ctx.moveTo(xOf(i - 1), yOf(pts[i - 1].los_h));  // גובה קו ראייה בנקודה הקודמת
2471                 ctx.lineTo(xOf(i),     yOf(pts[i].los_h));       // גובה קו ראייה בנקודה הנוכחית
2472                 ctx.strokeStyle = pts[i].visible ? '#00cc44' : '#ff3300';
2473                 ctx.lineWidth = 1.5; ctx.stroke();
2474             }}
2475 
2476             // קו אנכי מקווקו ציאן — רק כשמגיע מפרופיל מכ"ם-דופלר (typeof, לא !==, כי /los הרגיל
2477             // לא שולח את השדה הזה בכלל): מסמן היכן המכ"ם/דופלר הפסיקו לזהות, גם אם זה *לפני*
2478             // שהשטח עצמו חסם (קו הראייה הירוק ממשיך אחריו) — בדיוק ההבחנה שהמשתמש רצה לראות
2479             if (typeof data.radar_dist_km !== 'undefined' && data.radar_dist_km < pts[pts.length - 1].dist_km) {{
2480                 var idxAtRadar = pts.length - 1;
2481                 for (var ri = 0; ri < pts.length; ri++) {{  // מוצא את אינדקס הנקודה הקרוב ביותר למרחק הזה, לצורך מיקום ה-X
2482                     if (pts[ri].dist_km >= data.radar_dist_km) {{ idxAtRadar = ri; break; }}
2483                 }}
2484                 var xRadar = xOf(idxAtRadar);
2485                 ctx.beginPath();
2486                 ctx.setLineDash([4, 3]);
2487                 ctx.moveTo(xRadar, PAD.t); ctx.lineTo(xRadar, PAD.t + cH);
2488                 ctx.strokeStyle = '#22d3ee'; ctx.lineWidth = 1.5; ctx.stroke();
2489                 ctx.setLineDash([]);
2490             }}
2491 
2492             // שורת מידע עליונה: מרחק כולל + חסימה ראשונה (אם יש) + סטטוס דופלר (רק בפרופיל מכ"ם-דופלר)
2493             var info = data.total_km + ' ק"מ';
2494             if (data.first_block_km !== null) {{
2495                 info += '  ⛔ ' + data.first_block_km + 'ק';  // מרחק חסימה ראשונה
2496             }} else {{
2497                 info += '  ✓';  // ✓ ראייה מלאה לאורך כל המסלול
2498             }}
2499             if (typeof data.doppler_ok !== 'undefined' && !data.doppler_ok) {{
2500                 info += '  〰️ חסום-דופלר';  // כל הכיוון הזה עיוור לדופלר, ללא קשר לשטח
2501             }}
2502             ctx.fillStyle = '#aaa'; ctx.font = '10px Arial'; ctx.textAlign = 'center';
2503             ctx.fillText(info, PAD.l + cW / 2, PAD.t - 3);  // מעל אזור הגרף
2504         }}
