2762         function _onRadialHandleDrag(ev, which) {{
2763             // גרירת ידית — קובעת גם אזימוט (רק לידית הזו) וגם טווח משותף (שתי הידיות זזות לאותו רדיוס חדש),
2764             // כי כל ידית היא נקודה דו-ממדית חופשית אבל range_km הוא שדה אחד משותף למגזר כולו.
2765             if (!radialLosObs) return;
2766             var p = ev.target.getLatLng();
2767             var bearing = _bearingDeg(radialLosObs, p);   // הזווית של הידית הזו בלבד
2768             var distM   = _haversineM(radialLosObs, p);    // המרחק — משותף לשתי הידיות
2769             if (which === 'start' && _radialStartInput) _radialStartInput.value = bearing.toFixed(1);
2770             if (which === 'end'   && _radialEndInput)   _radialEndInput.value   = bearing.toFixed(1);
2771             if (_radialRangeInput) _radialRangeInput.value = (distM / 1000).toFixed(2);  // מעדכן את שדה הטווח המשותף
2772             _updateRadialLosPreview();  // מצייר מחדש את שני הקווים ברדיוס החדש + הזוויות המעודכנות
2773         }}
