3101         function _updateRadarDopplerPreview() {{
3102             // מצייר/מעדכן את שני קווי התצוגה המקדימה (אזימוט התחלה/סוף) + הידיות בקצותיהם —
3103             // אותה טכניקה בדיוק כמו _updateRadialLosPreview, חישוב מקומי בלבד, בלי לקרוא לשרת
3104             if (!radarObs) return;  // אין עדיין נקודת תצפית — אין מה לצייר
3105             var rangeKm  = _radarRangeInput ? parseFloat(_radarRangeInput.value) : NaN;
3106             var startDeg = _radarStartInput ? parseFloat(_radarStartInput.value) : NaN;
3107             var endDeg   = _radarEndInput   ? parseFloat(_radarEndInput.value)   : NaN;
3108             if (isNaN(rangeKm))  rangeKm  = 50;  // ברירת מחדל — תואמת לברירת המחדל בשרת (שונה מרדיוס-הראייה: 50, לא 5)
3109             if (isNaN(startDeg)) startDeg = 315; // מגזר 90° סביב צפון כברירת מחדל — לא מעגל מלא חופף
3110             if (isNaN(endDeg))   endDeg   = 45;
3111             var startPt = _destPointJs(radarObs, startDeg, rangeKm * 1000);
3112             var endPt   = _destPointJs(radarObs, endDeg,   rangeKm * 1000);
3113             if (radarStartLn) map.removeLayer(radarStartLn);  // מנקה קו קודם לפני ציור מחדש
3114             if (radarEndLn)   map.removeLayer(radarEndLn);
