3116             radarEndLn   = L.polyline([radarObs, endPt],   {{color:'#22d3ee', weight:1.5, dashArray:'4,4'}}).addTo(map);
3117             if (!radarStartMk) {{  // יוצר את הידית פעם אחת בלבד — בפעמים הבאות רק מזיז אותה
3118                 radarStartMk = L.marker(startPt, {{icon: _radarHandleIcon(), draggable:true}}).addTo(map);
3119                 radarStartMk.on('drag', function(ev) {{ _onRadarHandleDrag(ev, 'start'); }});
3120             }} else {{
3121                 radarStartMk.setLatLng(startPt);
3122             }}
3123             if (!radarEndMk) {{
3124                 radarEndMk = L.marker(endPt, {{icon: _radarHandleIcon(), draggable:true}}).addTo(map);
3125                 radarEndMk.on('drag', function(ev) {{ _onRadarHandleDrag(ev, 'end'); }});
