3131         function _onRadarHandleDrag(ev, which) {{
3132             // גרירת ידית — קובעת גם אזימוט (רק לידית הזו) וגם טווח משותף (שתי הידיות זזות לאותו רדיוס חדש)
3133             if (!radarObs) return;
3134             var p = ev.target.getLatLng();
3135             var bearing = _bearingDeg(radarObs, p);
3136             var distM   = _haversineM(radarObs, p);
3137             if (which === 'start' && _radarStartInput) _radarStartInput.value = bearing.toFixed(1);
3138             if (which === 'end'   && _radarEndInput)   _radarEndInput.value   = bearing.toFixed(1);
3139             if (_radarRangeInput) _radarRangeInput.value = (distM / 1000).toFixed(2);
