3143         function _runRadarDoppler() {{
3144             // מפעיל את החישוב האמיתי בשרת — נקרא רק בלחיצה מפורשת על "הפעל חישוב"
3145             if (!radarObs || radarLoading) return;
3146             function num(el, def) {{ var v = el ? parseFloat(el.value) : NaN; return isNaN(v) ? def : v; }}
3147             var rangeKm    = num(_radarRangeInput, 50);
